#include <map>
#include <algorithm>

template <class K, class V>
struct ValueEquals {
    V target_value;
    ValueEquals(const V& v) : target_value(v) {}

    // CRITICAL: Argument must match map::value_type: pair<const K, V>
    bool operator() (const std::pair<const K, V>& elem) const {
        return elem.second == target_value;
    }
};

int main() {
    std::map<int, double> m = {{1, 1.1}, {2, 2.2}};
    auto pos = std::find_if(m.begin(), m.end(), 
        ValueEquals<int, double>(2.2)
    );
    // pos now points to {2, 2.2}
}
